rules.pseudocode:
// long-side reading = three pushes DOWN (a bull setup); pivots are confirmed SwingLow(swingStrength)
p1 = swingLow(3, swingStrength); p2 = swingLow(2, swingStrength); p3 = swingLow(1, swingStrength);
allWithinWindow = barsAgo(p1) <= lookbackBars;
extendsEnough = (p2 <= p1 - minPushExtensionTicks * tick) && (p3 <= p2 - minPushExtensionTicks * tick);
notTooFar = maxPushExtensionTicks == 0 || ((p1 - p2) <= maxPushExtensionTicks * tick && (p2 - p3) <= maxPushExtensionTicks * tick);
// shapeMode 0 = any shape (Brooks's own position), 1 = converging (wedge), 2 = diverging (expanding)
lowerLineSlope = slope(p1, p3); upperLineSlope = slope(swingHigh(2, swingStrength), swingHigh(1, swingStrength));
shapeOk = shapeMode == 0
  || (shapeMode == 1 && lowerLineSlope > upperLineSlope * convergenceMultiple)
  || (shapeMode == 2 && lowerLineSlope < upperLineSlope);
isThreePushPattern = allWithinWindow && extendsEnough && notTooFar && shapeOk

// minLegs alternating pivots, both sides pushing further out
expandingHighs = swingHigh(1, s) > swingHigh(2, s) && swingHigh(2, s) > swingHigh(3, s);
expandingLows  = swingLow(1, s)  < swingLow(2, s)  && swingLow(2, s)  < swingLow(3, s);
isExpandingTriangle = expandingHighs && expandingLows && pivotCountWithin(lookbackBars) >= minLegs

// long-side reading on a wedge TOP being faded short; mirrored on lows
late  = swingHigh(1, s) - swingHigh(2, s);
early = swingHigh(2, s) - swingHigh(3, s);
if perBar == 1 { late = late / barsBetween(swingHigh(1,s), swingHigh(2,s)); early = early / barsBetween(swingHigh(2,s), swingHigh(3,s)); }
isAccelerating = early > 0 && late > early * accelMultiple

firstSignalBar = bar where ThreePushReversalEntry fired, k bars ago, k <= withinBars;
firstSignalFailed = low[0] < low[firstSignalBar];  // long case: the first attempt gave way
secondEntry = firstSignalFailed && low[0] > patternExtreme && close[0] > high[1]

// R04-02's concrete form, the only bar-level test offered
isResetBar = close[0] > open[0] && (close[0] - open[0]) >= bodyFraction * (high[0] - low[0]) && (high[0] - low[0]) >= resetRangeMultiple * atr(atrLookback);
// on a reset bar the push counter restarts at 1

correctionBars = currentBarIndex - barIndexOf(patternExtreme);
patternBars = barIndexOf(patternExtreme) - barIndexOf(firstPush);
correctionAdequate = correctionBars >= minCorrectionFraction * patternBars

flagHigh = highest(high, flagBars)[1]; flagLow = lowest(low, flagBars)[1];
brokeOut = requirePriorBreakout == 0 || (highest(high, priorBreakoutWindow)[1] > flagHigh);
isFinalFlagCandidate[1] && brokeOut && close[0] < flagLow

recent = highest(high, flagBars) - lowest(low, flagBars);
prior  = highest(high, flagBars)[flagBars] - lowest(low, flagBars)[flagBars];
recent < shrinkFraction * prior

// long: target the pivotIndex-th most recent swing high
target = swingHigh(pivotIndex, swingStrength);
ctx.MarketPosition() > 0 && high[0] >= target
